  "root_required_only": {
    "derived_under_policy": "SPK-001",
    "summary": "Derived categorical construction for PO035 §5 eight-stage spine with three rational fibers; identity-transport control verified; obstruction to curvature derivation conditional on flat relation holding.",
    "seed_allows_theory_refutation": true,
